         """docstring"""
        pass
```

into a construct using a metaclass

```python
class MetaClass:
    @property
    def fun(cls):
        """docstring"""

class A(metaclass=MetaClass):
    fun = classmethod(MetaClass.fun)
    """docstring"""
```

